from collections import Counter
import json
def comps(g,bg):
    h=len(g);w=len(g[0]);seen=set();out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and (i,j) not in seen:
                st=[(i,j)];cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b));cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w and g[x][y]==bg and (x,y) not in seen: st.append((x,y))
                out.append(cells)
    return out
