    print(k,'bg',bg,'ncomps',len(cs),'sizes',sorted(Counter(len(c) for c in cs).items()))
    big=max(cs,key=len)
    rs=[a for a,b in big];cs_=[b for a,b in big]
    print('  biggest bbox',(min(rs),min(cs_),max(rs),max(cs_)))

