import os,re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def blocks(g,mk):
    h=len(g);w=len(g[0]);Bs=[];seen=set()
    for i in range(h-1):
        for j in range(w-1):
            if g[i][j]==mk and g[i+1][j]==mk and g[i][j+1]==mk and g[i+1][j+1]==mk and (i,j) not in seen:
                Bs.append([(i,j),(i,j+1),(i+1,j),(i+1,j+1)]);seen.update([(i,j),(i,j+1),(i+1,j),(i+1,j+1)])
    return Bs
for k in ['Demo pair 1 input','Demo pair 2 input','Demo pair 3 input','Demo pair 4 input','Demo pair 5 input','Test input']:
